import { t } from 'elysia'

export const AccountAnnualRevenueSchema = t.Object(
  {
    amount: t.Optional(
      t.Union([
        t.Integer({
          maximum: 9007199254740991,
          description:
            'A non-negative integer representing the amount in the [smallest currency unit](/currencies#zero-decimal).',
        }),
        t.Null(),
      ]),
    ),
    currency: t.Optional(
      t.Union([
        t.String({
          description:
            'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
        }),
        t.Null(),
      ]),
    ),
    fiscal_year_end: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description:
            'The close-out date of the preceding fiscal year in ISO 8601 format. E.g. 2023-12-31 for the 31st of December, 2023.',
        }),
        t.Null(),
      ]),
    ),
  },
  { title: 'AccountAnnualRevenue', description: '' },
)

export const AccountMonthlyEstimatedRevenueSchema = t.Object(
  {
    amount: t.Integer({
      maximum: 9007199254740991,
      description:
        'A non-negative integer representing how much to charge in the [smallest currency unit](/currencies#zero-decimal).',
    }),
    currency: t.String({
      description:
        'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
    }),
  },
  { title: 'AccountMonthlyEstimatedRevenue', description: '' },
)

export const AddressSchema = t.Object(
  {
    city: t.Optional(
      t.Union([
        t.String({ maxLength: 5000, description: 'City, district, suburb, town, or village.' }),
        t.Null(),
      ]),
    ),
    country: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description:
            'Two-letter country code ([ISO 3166-1 alpha-2](https://en.wikipedia.org/wiki/ISO_3166-1_alpha-2)).',
        }),
        t.Null(),
      ]),
    ),
    line1: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description: 'Address line 1, such as the street, PO Box, or company name.',
        }),
        t.Null(),
      ]),
    ),
    line2: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description: 'Address line 2, such as the apartment, suite, unit, or building.',
        }),
        t.Null(),
      ]),
    ),
    postal_code: t.Optional(
      t.Union([t.String({ maxLength: 5000, description: 'ZIP or postal code.' }), t.Null()]),
    ),
    state: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description:
            'State, county, province, or region ([ISO 3166-2](https://en.wikipedia.org/wiki/ISO_3166-2)).',
        }),
        t.Null(),
      ]),
    ),
  },
  { title: 'Address', description: '' },
)

export const AccountBusinessProfileSchema = t.Object(
  {
    annual_revenue: t.Optional(t.Union([AccountAnnualRevenueSchema, t.Null()])),
    estimated_worker_count: t.Optional(
      t.Union([
        t.Integer({
          maximum: 9007199254740991,
          description:
            'An estimated upper bound of employees, contractors, vendors, etc. currently working for the business.',
        }),
        t.Null(),
      ]),
    ),
    mcc: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description:
            '[The merchant category code for the account](/connect/setting-mcc). MCCs are used to classify businesses based on the goods or services they provide.',
        }),
        t.Null(),
      ]),
    ),
    minority_owned_business_designation: t.Optional(
      t.Union([
        t.Array(
          t.UnionEnum(
            [
              'lgbtqi_owned_business',
              'minority_owned_business',
              'none_of_these_apply',
              'prefer_not_to_answer',
              'women_owned_business',
            ],
            { default: undefined },
          ),
          {
            description:
              'Whether the business is a minority-owned, women-owned, and/or LGBTQI+ -owned business.',
          },
        ),
        t.Null(),
      ]),
    ),
    monthly_estimated_revenue: t.Optional(AccountMonthlyEstimatedRevenueSchema),
    name: t.Optional(
      t.Union([
        t.String({ maxLength: 5000, description: 'The customer-facing business name.' }),
        t.Null(),
      ]),
    ),
    product_description: t.Optional(
      t.Union([
        t.String({
          maxLength: 40000,
          description:
            "Internal-only description of the product sold or service provided by the business. It's used by Stripe for risk and underwriting purposes.",
        }),
        t.Null(),
      ]),
    ),
    specified_commercial_transactions_act_url: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description:
            "A link to the business's publicly available terms related to the Specified Commercial Transaction Act. Only used for accounts in Japan.",
        }),
        t.Null(),
      ]),
    ),
    support_address: t.Optional(t.Union([AddressSchema, t.Null()])),
    support_email: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description: 'A publicly available email address for sending support issues to.',
        }),
        t.Null(),
      ]),
    ),
    support_phone: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description: 'A publicly available phone number to call with support issues.',
        }),
        t.Null(),
      ]),
    ),
    support_url: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description: 'A publicly available website for handling support issues.',
        }),
        t.Null(),
      ]),
    ),
    url: t.Optional(
      t.Union([
        t.String({ maxLength: 5000, description: "The business's publicly available website." }),
        t.Null(),
      ]),
    ),
  },
  { title: 'AccountBusinessProfile', description: '' },
)

