export const SourceSchema = t.Object(
  {
    ach_credit_transfer: t.Optional(SourceTypeAchCreditTransferSchema),
    ach_debit: t.Optional(SourceTypeAchDebitSchema),
    acss_debit: t.Optional(SourceTypeAcssDebitSchema),
    alipay: t.Optional(SourceTypeAlipaySchema),
    allow_redisplay: t.Optional(
      t.Union([
        t.UnionEnum(['always', 'limited', 'unspecified'], {
          description:
            'This field indicates whether this payment method can be shown again to its customer in a checkout flow. Stripe products such as Checkout and Elements use this field to determine whether a payment method can be shown as a saved payment method in a checkout flow. The field defaults to “unspecified”.',
          default: undefined,
        }),
        t.Null(),
      ]),
    ),
    amount: t.Optional(
      t.Union([
        t.Integer({
          maximum: 9007199254740991,
          description:
            'A positive integer in the smallest currency unit (that is, 100 cents for $1.00, or 1 for ¥1, Japanese Yen being a zero-decimal currency) representing the total amount associated with the source. This is the amount for which the source will be chargeable once ready. Required for `single_use` sources.',
        }),
        t.Null(),
      ]),
    ),
    au_becs_debit: t.Optional(SourceTypeAuBecsDebitSchema),
    bancontact: t.Optional(SourceTypeBancontactSchema),
    card: t.Optional(SourceTypeCardSchema),
    card_present: t.Optional(SourceTypeCardPresentSchema),
    client_secret: t.String({
      maxLength: 5000,
      description:
        'The client secret of the source. Used for client-side retrieval using a publishable key.',
    }),
    code_verification: t.Optional(SourceCodeVerificationFlowSchema),
    created: t.Integer({
      format: 'unix-time',
      maximum: 9007199254740991,
      description:
        'Time at which the object was created. Measured in seconds since the Unix epoch.',
    }),
    currency: t.Optional(
      t.Union([
        t.String({
          description:
            'Three-letter [ISO code for the currency](https://stripe.com/docs/currencies) associated with the source. This is the currency for which the source will be chargeable once ready. Required for `single_use` sources.',
        }),
        t.Null(),
      ]),
    ),
    customer: t.Optional(
      t.String({
        maxLength: 5000,
        description:
          'The ID of the customer to which this source is attached. This will not be present when the source has not been attached to a customer.',
      }),
    ),
    eps: t.Optional(SourceTypeEpsSchema),
    flow: t.String({
      maxLength: 5000,
      description:
        'The authentication `flow` of the source. `flow` is one of `redirect`, `receiver`, `code_verification`, `none`.',
    }),
    giropay: t.Optional(SourceTypeGiropaySchema),
    id: t.String({ maxLength: 5000, description: 'Unique identifier for the object.' }),
    ideal: t.Optional(SourceTypeIdealSchema),
    klarna: t.Optional(SourceTypeKlarnaSchema),
    livemode: t.Boolean({
      description:
        'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
    }),
    metadata: t.Optional(
      t.Union([
        t.Record(t.String(), t.String({ maxLength: 500 }), {
          description:
            'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
        }),
        t.Null(),
      ]),
    ),
    multibanco: t.Optional(SourceTypeMultibancoSchema),
    object: t.Literal('source', {
      description:
        "String representing the object's type. Objects of the same type share the same value.",
    }),
    owner: t.Optional(t.Union([SourceOwnerSchema, t.Null()])),
    p24: t.Optional(SourceTypeP24Schema),
    receiver: t.Optional(SourceReceiverFlowSchema),
    redirect: t.Optional(SourceRedirectFlowSchema),
    sepa_debit: t.Optional(SourceTypeSepaDebitSchema),
    sofort: t.Optional(SourceTypeSofortSchema),
    source_order: t.Optional(SourceOrderSchema),
    statement_descriptor: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description:
            "Extra information about a source. This will appear on your customer's statement every time you charge the source.",
        }),
        t.Null(),
      ]),
    ),
    status: t.String({
      maxLength: 5000,
      description:
        'The status of the source, one of `canceled`, `chargeable`, `consumed`, `failed`, or `pending`. Only `chargeable` sources can be used to create a charge.',
    }),
    three_d_secure: t.Optional(SourceTypeThreeDSecureSchema),
    type: t.UnionEnum(
      [
        'ach_credit_transfer',
        'ach_debit',
        'acss_debit',
        'alipay',
        'au_becs_debit',
        'bancontact',
        'card',
        'card_present',
        'eps',
        'giropay',
        'ideal',
        'klarna',
        'multibanco',
        'p24',
        'sepa_debit',
        'sofort',
        'three_d_secure',
        'wechat',
      ],
      {
        description:
          'The `type` of the source. The `type` is a payment method, one of `ach_credit_transfer`, `ach_debit`, `alipay`, `bancontact`, `card`, `card_present`, `eps`, `giropay`, `ideal`, `multibanco`, `klarna`, `p24`, `sepa_debit`, `sofort`, `three_d_secure`, or `wechat`. An additional hash is included on the source with a name matching this value. It contains additional information specific to the [payment method](https://docs.stripe.com/sources) used.',
        default: undefined,
      },
    ),
    usage: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description:
            'Either `reusable` or `single_use`. Whether this source should be reusable or not. Some source types may or may not be reusable by construction, while others may leave the option at creation. If an incompatible value is passed, an error will be returned.',
        }),
        t.Null(),
      ]),
    ),
    wechat: t.Optional(SourceTypeWechatSchema),
  },
  {
    title: 'Source',
    description:
      "`Source` objects allow you to accept a variety of payment methods. They\nrepresent a customer's payment instrument, and can be used with the Stripe API\njust like a `Card` object: once chargeable, they can be charged, or can be\nattached to customers.\n\nStripe doesn't recommend using the deprecated [Sources API](https://docs.stripe.com/api/sources).\nWe recommend that you adopt the [PaymentMethods API](https://docs.stripe.com/api/payment_methods).\nThis newer API provides access to our latest features and payment method types.\n\nRelated guides: [Sources API](https://docs.stripe.com/sources) and [Sources & Customers](https://docs.stripe.com/sources/customers).",
  },
)

