export const MandatePaytoSchema = t.Object(
  {
    amount: t.Optional(
      t.Union([
        t.Integer({
          maximum: 9007199254740991,
          description:
            'Amount that will be collected. It is required when `amount_type` is `fixed`.',
        }),
        t.Null(),
      ]),
    ),
    amount_type: t.UnionEnum(['fixed', 'maximum'], {
      description:
        'The type of amount that will be collected. The amount charged must be exact or up to the value of `amount` param for `fixed` or `maximum` type respectively. Defaults to `maximum`.',
      default: undefined,
    }),
    end_date: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description:
            'Date, in YYYY-MM-DD format, after which payments will not be collected. Defaults to no end date.',
        }),
        t.Null(),
      ]),
    ),
    payment_schedule: t.UnionEnum(
      ['adhoc', 'annual', 'daily', 'fortnightly', 'monthly', 'quarterly', 'semi_annual', 'weekly'],
      {
        description: 'The periodicity at which payments will be collected. Defaults to `adhoc`.',
        default: undefined,
      },
    ),
    payments_per_period: t.Optional(
      t.Union([
        t.Integer({
          maximum: 9007199254740991,
          description:
            'The number of payments that will be made during a payment period. Defaults to 1 except for when `payment_schedule` is `adhoc`. In that case, it defaults to no limit.',
        }),
        t.Null(),
      ]),
    ),
    purpose: t.Optional(
      t.Union([
        t.UnionEnum(
          [
            'dependant_support',
            'government',
            'loan',
            'mortgage',
            'other',
            'pension',
            'personal',
            'retail',
            'salary',
            'tax',
            'utility',
          ],
          {
            description:
              'The purpose for which payments are made. Has a default value based on your merchant category code.',
            default: undefined,
          },
        ),
        t.Null(),
      ]),
    ),
    start_date: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description:
            'Date, in YYYY-MM-DD format, from which payments will be collected. Defaults to confirmation time.',
        }),
        t.Null(),
      ]),
    ),
  },
  { title: 'mandate_payto', description: '' },
)

