export const ThreeDSecureDetailsSchema = t.Object(
  {
    authentication_flow: t.Optional(
      t.Union([
        t.UnionEnum(['challenge', 'frictionless'], {
          description:
            'For authenticated transactions: how the customer was authenticated by\nthe issuing bank.',
          default: undefined,
        }),
        t.Null(),
      ]),
    ),
    electronic_commerce_indicator: t.Optional(
      t.Union([
        t.UnionEnum(['01', '02', '05', '06', '07'], {
          description:
            'The Electronic Commerce Indicator (ECI). A protocol-level field\nindicating what degree of authentication was performed.',
          default: undefined,
        }),
        t.Null(),
      ]),
    ),
    result: t.Optional(
      t.Union([
        t.UnionEnum(
          [
            'attempt_acknowledged',
            'authenticated',
            'data_share_only',
            'exempted',
            'failed',
            'not_supported',
            'processing_error',
          ],
          { description: 'Indicates the outcome of 3D Secure authentication.', default: undefined },
        ),
        t.Null(),
      ]),
    ),
    result_reason: t.Optional(
      t.Union([
        t.UnionEnum(
          [
            'abandoned',
            'bypassed',
            'canceled',
            'card_not_enrolled',
            'network_not_supported',
            'protocol_error',
            'rejected',
          ],
          {
            description:
              'Additional information about why 3D Secure succeeded or failed based\non the `result`.',
            default: undefined,
          },
        ),
        t.Null(),
      ]),
    ),
    transaction_id: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description:
            'The 3D Secure 1 XID or 3D Secure 2 Directory Server Transaction ID\n(dsTransId) for this payment.',
        }),
        t.Null(),
      ]),
    ),
    version: t.Optional(
      t.Union([
        t.UnionEnum(['1.0.2', '2.1.0', '2.2.0', '2.3.0', '2.3.1'], {
          description: 'The version of 3D Secure that was used.',
          default: undefined,
        }),
        t.Null(),
      ]),
    ),
  },
  { title: 'three_d_secure_details', description: '' },
)

