export const PaymentIntentAmountDetailsLineItemSchema = t.Object(
  {
    discount_amount: t.Optional(
      t.Union([
        t.Integer({
          maximum: 9007199254740991,
          description:
            'The discount applied on this line item represented in the [smallest currency unit](https://docs.stripe.com/currencies#zero-decimal). An integer greater than 0.\n\nThis field is mutually exclusive with the `amount_details[discount_amount]` field.',
        }),
        t.Null(),
      ]),
    ),
    id: t.String({ maxLength: 5000, description: 'Unique identifier for the object.' }),
    object: t.Literal('payment_intent_amount_details_line_item', {
      description:
        "String representing the object's type. Objects of the same type share the same value.",
    }),
    payment_method_options: t.Optional(
      t.Union([
        PaymentFlowsAmountDetailsResourceLineItemsListResourceLineItemResourcePaymentMethodOptionsSchema,
        t.Null(),
      ]),
    ),
    product_code: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description:
            'The product code of the line item, such as an SKU. Required for L3 rates. At most 12 characters long.',
        }),
        t.Null(),
      ]),
    ),
    product_name: t.String({
      maxLength: 5000,
      description:
        'The product name of the line item. Required for L3 rates. At most 1024 characters long.\n\nFor Cards, this field is truncated to 26 alphanumeric characters before being sent to the card networks. For PayPal, this field is truncated to 127 characters.',
    }),
    quantity: t.Integer({
      maximum: 9007199254740991,
      description: 'The quantity of items. Required for L3 rates. An integer greater than 0.',
    }),
    tax: t.Optional(
      t.Union([
        PaymentFlowsAmountDetailsResourceLineItemsListResourceLineItemResourceTaxSchema,
        t.Null(),
      ]),
    ),
    unit_cost: t.Integer({
      maximum: 9007199254740991,
      description:
        'The unit cost of the line item represented in the [smallest currency unit](https://docs.stripe.com/currencies#zero-decimal). Required for L3 rates. An integer greater than or equal to 0.',
    }),
    unit_of_measure: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description:
            'A unit of measure for the line item, such as gallons, feet, meters, etc. Required for L3 rates. At most 12 alphanumeric characters long.',
        }),
        t.Null(),
      ]),
    ),
  },
  { title: 'PaymentIntent LineItem', description: '' },
)

