export const IssuingCardSchema = t.Recursive((Self) =>
  t.Object(
    {
      brand: t.String({ maxLength: 5000, description: 'The brand of the card.' }),
      cancellation_reason: t.Optional(
        t.Union([
          t.UnionEnum(['design_rejected', 'fulfillment_error', 'lost', 'stolen'], {
            description: 'The reason why the card was canceled.',
            default: undefined,
          }),
          t.Null(),
        ]),
      ),
      cardholder: IssuingCardholderSchema,
      created: t.Integer({
        format: 'unix-time',
        maximum: 9007199254740991,
        description:
          'Time at which the object was created. Measured in seconds since the Unix epoch.',
      }),
      currency: t.String({
        description:
          'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Supported currencies are `usd` in the US, `eur` in the EU, and `gbp` in the UK.',
      }),
      cvc: t.Optional(
        t.String({
          maxLength: 5000,
          description:
            'The card\'s CVC. For security reasons, this is only available for virtual cards, and will be omitted unless you explicitly request it with [the `expand` parameter](https://docs.stripe.com/api/expanding_objects). Additionally, it\'s only available via the ["Retrieve a card" endpoint](https://docs.stripe.com/api/issuing/cards/retrieve), not via "List all cards" or any other endpoint.',
        }),
      ),
      exp_month: t.Integer({
        maximum: 9007199254740991,
        description: 'The expiration month of the card.',
      }),
      exp_year: t.Integer({
        maximum: 9007199254740991,
        description: 'The expiration year of the card.',
      }),
      financial_account: t.Optional(
        t.Union([
          t.String({
            maxLength: 5000,
            description: 'The financial account this card is attached to.',
          }),
          t.Null(),
        ]),
      ),
      id: t.String({ maxLength: 5000, description: 'Unique identifier for the object.' }),
      last4: t.String({ maxLength: 5000, description: 'The last 4 digits of the card number.' }),
      latest_fraud_warning: t.Optional(t.Union([IssuingCardFraudWarningSchema, t.Null()])),
      lifecycle_controls: t.Optional(t.Union([IssuingCardLifecycleControlsSchema, t.Null()])),
      livemode: t.Boolean({
        description:
          'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
      }),
      metadata: t.Record(t.String(), t.String({ maxLength: 500 }), {
        description:
          'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
      }),
      number: t.Optional(
        t.String({
          maxLength: 5000,
          description:
            'The full unredacted card number. For security reasons, this is only available for virtual cards, and will be omitted unless you explicitly request it with [the `expand` parameter](https://docs.stripe.com/api/expanding_objects). Additionally, it\'s only available via the ["Retrieve a card" endpoint](https://docs.stripe.com/api/issuing/cards/retrieve), not via "List all cards" or any other endpoint.',
        }),
      ),
      object: t.Literal('issuing.card', {
        description:
          "String representing the object's type. Objects of the same type share the same value.",
      }),
      personalization_design: t.Optional(
        t.Union([
          t.Union([t.String({ maxLength: 5000 }), IssuingPersonalizationDesignSchema], {
            description: 'The personalization design object belonging to this card.',
          }),
          t.Null(),
        ]),
      ),
      replaced_by: t.Optional(
        t.Union([
          t.Union([t.String({ maxLength: 5000 }), Self], {
            description: 'The latest card that replaces this card, if any.',
          }),
          t.Null(),
        ]),
      ),
      replacement_for: t.Optional(
        t.Union([
          t.Union([t.String({ maxLength: 5000 }), Self], {
            description: 'The card this card replaces, if any.',
          }),
          t.Null(),
        ]),
      ),
      replacement_reason: t.Optional(
        t.Union([
          t.UnionEnum(['damaged', 'expired', 'fulfillment_error', 'lost', 'stolen'], {
            description: 'The reason why the previous card needed to be replaced.',
            default: undefined,
          }),
          t.Null(),
        ]),
      ),
      second_line: t.Optional(
        t.Union([
          t.String({
            maxLength: 5000,
            description: 'Text separate from cardholder name, printed on the card.',
          }),
          t.Null(),
        ]),
      ),
      shipping: t.Optional(t.Union([IssuingCardShippingSchema, t.Null()])),
      spending_controls: IssuingCardAuthorizationControlsSchema,
      status: t.UnionEnum(['active', 'canceled', 'inactive'], {
        description:
          'Whether authorizations can be approved on this card. May be blocked from activating cards depending on past-due Cardholder requirements. Defaults to `inactive`.',
        default: undefined,
      }),
      type: t.UnionEnum(['physical', 'virtual'], {
        description: 'The type of the card.',
        default: undefined,
      }),
      wallets: t.Optional(t.Union([IssuingCardWalletsSchema, t.Null()])),
    },
    {
      title: 'Card',
      description:
        'You can [create physical or virtual cards](https://docs.stripe.com/issuing) that are issued to cardholders.',
    },
  ),
)

