export const ConfirmationTokenSchema = t.Object(
  {
    created: t.Integer({
      format: 'unix-time',
      maximum: 9007199254740991,
      description:
        'Time at which the object was created. Measured in seconds since the Unix epoch.',
    }),
    expires_at: t.Optional(
      t.Union([
        t.Integer({
          format: 'unix-time',
          maximum: 9007199254740991,
          description:
            'Time at which this ConfirmationToken expires and can no longer be used to confirm a PaymentIntent or SetupIntent.',
        }),
        t.Null(),
      ]),
    ),
    id: t.String({ maxLength: 5000, description: 'Unique identifier for the object.' }),
    livemode: t.Boolean({
      description:
        'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
    }),
    mandate_data: t.Optional(t.Union([ConfirmationTokensResourceMandateDataSchema, t.Null()])),
    metadata: t.Optional(
      t.Union([
        t.Record(t.String(), t.String({ maxLength: 500 }), {
          description:
            'Set of key-value pairs that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
        }),
        t.Null(),
      ]),
    ),
    object: t.Literal('confirmation_token', {
      description:
        "String representing the object's type. Objects of the same type share the same value.",
    }),
    payment_intent: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description:
            'ID of the PaymentIntent that this ConfirmationToken was used to confirm, or null if this ConfirmationToken has not yet been used.',
        }),
        t.Null(),
      ]),
    ),
    payment_method_options: t.Optional(
      t.Union([ConfirmationTokensResourcePaymentMethodOptionsSchema, t.Null()]),
    ),
    payment_method_preview: t.Optional(
      t.Union([ConfirmationTokensResourcePaymentMethodPreviewSchema, t.Null()]),
    ),
    return_url: t.Optional(
      t.Union([
        t.String({ maxLength: 5000, description: 'Return URL used to confirm the Intent.' }),
        t.Null(),
      ]),
    ),
    setup_future_usage: t.Optional(
      t.Union([
        t.UnionEnum(['off_session', 'on_session'], {
          description:
            "Indicates that you intend to make future payments with this ConfirmationToken's payment method.\n\nThe presence of this property will [attach the payment method](https://docs.stripe.com/payments/save-during-payment) to the PaymentIntent's Customer, if present, after the PaymentIntent is confirmed and any required actions from the user are complete.",
          default: undefined,
        }),
        t.Null(),
      ]),
    ),
    setup_intent: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description:
            'ID of the SetupIntent that this ConfirmationToken was used to confirm, or null if this ConfirmationToken has not yet been used.',
        }),
        t.Null(),
      ]),
    ),
    shipping: t.Optional(t.Union([ConfirmationTokensResourceShippingSchema, t.Null()])),
    use_stripe_sdk: t.Boolean({
      description:
        'Indicates whether the Stripe SDK is used to handle confirmation flow. Defaults to `true` on ConfirmationToken.',
    }),
  },
  {
    title: 'Confirmation Token',
    description:
      'ConfirmationTokens help transport client side data collected by Stripe JS over\nto your server for confirming a PaymentIntent or SetupIntent. If the confirmation\nis successful, values present on the ConfirmationToken are written onto the Intent.\n\nTo learn more about how to use ConfirmationToken, visit the related guides:\n- [Finalize payments on the server](https://docs.stripe.com/payments/finalize-payments-on-the-server)\n- [Build two-step confirmation](https://docs.stripe.com/payments/build-a-two-step-confirmation).',
  },
)

