export const CountrySpecSchema = t.Object(
  {
    default_currency: t.String({
      maxLength: 5000,
      description:
        'The default currency for this country. This applies to both payment methods and bank accounts.',
    }),
    id: t.String({
      maxLength: 5000,
      description:
        'Unique identifier for the object. Represented as the ISO country code for this country.',
    }),
    object: t.Literal('country_spec', {
      description:
        "String representing the object's type. Objects of the same type share the same value.",
    }),
    supported_bank_account_currencies: t.Record(
      t.String(),
      t.Array(t.String({ maxLength: 5000 })),
      { description: 'Currencies that can be accepted in the specific country (for transfers).' },
    ),
    supported_payment_currencies: t.Array(t.String({ maxLength: 5000 }), {
      description: 'Currencies that can be accepted in the specified country (for payments).',
    }),
    supported_payment_methods: t.Array(t.String({ maxLength: 5000 }), {
      description:
        'Payment methods available in the specified country. You may need to enable some payment methods (e.g., [ACH](https://stripe.com/docs/ach)) on your account before they appear in this list. The `stripe` payment method refers to [charging through your platform](https://stripe.com/docs/connect/destination-charges).',
    }),
    supported_transfer_countries: t.Array(t.String({ maxLength: 5000 }), {
      description: 'Countries that can accept transfers from the specified country.',
    }),
    verification_fields: CountrySpecVerificationFieldsSchema,
  },
  {
    title: 'Country Spec',
    description:
      "Stripe needs to collect certain pieces of information about each account\ncreated. These requirements can differ depending on the account's country. The\nCountry Specs API makes these rules available to your integration.\n\nYou can also view the information from this API call as [an online\nguide](/docs/connect/required-verification-information).",
  },
)

