export const PlanSchema = t.Object(
  {
    active: t.Boolean({ description: 'Whether the plan can be used for new purchases.' }),
    amount: t.Optional(
      t.Union([
        t.Integer({
          maximum: 9007199254740991,
          description:
            'The unit amount in cents (or local equivalent) to be charged, represented as a whole integer if possible. Only set if `billing_scheme=per_unit`.',
        }),
        t.Null(),
      ]),
    ),
    amount_decimal: t.Optional(
      t.Union([
        t.String({
          description:
            'The unit amount in cents (or local equivalent) to be charged, represented as a decimal string with at most 12 decimal places. Only set if `billing_scheme=per_unit`.',
        }),
        t.Null(),
      ]),
    ),
    billing_scheme: t.UnionEnum(['per_unit', 'tiered'], {
      description:
        'Describes how to compute the price per period. Either `per_unit` or `tiered`. `per_unit` indicates that the fixed amount (specified in `amount`) will be charged per unit in `quantity` (for plans with `usage_type=licensed`), or per unit of total usage (for plans with `usage_type=metered`). `tiered` indicates that the unit pricing will be computed using a tiering strategy as defined using the `tiers` and `tiers_mode` attributes.',
      default: undefined,
    }),
    created: t.Integer({
      format: 'unix-time',
      maximum: 9007199254740991,
      description:
        'Time at which the object was created. Measured in seconds since the Unix epoch.',
    }),
    currency: t.String({
      description:
        'Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).',
    }),
    id: t.String({ maxLength: 5000, description: 'Unique identifier for the object.' }),
    interval: t.UnionEnum(['day', 'month', 'week', 'year'], {
      description:
        'The frequency at which a subscription is billed. One of `day`, `week`, `month` or `year`.',
      default: undefined,
    }),
    interval_count: t.Integer({
      maximum: 9007199254740991,
      description:
        'The number of intervals (specified in the `interval` attribute) between subscription billings. For example, `interval=month` and `interval_count=3` bills every 3 months.',
    }),
    livemode: t.Boolean({
      description:
        'If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.',
    }),
    metadata: t.Optional(
      t.Union([
        t.Record(t.String(), t.String({ maxLength: 500 }), {
          description:
            'Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.',
        }),
        t.Null(),
      ]),
    ),
    meter: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description: 'The meter tracking the usage of a metered price',
        }),
        t.Null(),
      ]),
    ),
    nickname: t.Optional(
      t.Union([
        t.String({
          maxLength: 5000,
          description: 'A brief description of the plan, hidden from customers.',
        }),
        t.Null(),
      ]),
    ),
    object: t.Literal('plan', {
      description:
        "String representing the object's type. Objects of the same type share the same value.",
    }),
    product: t.Optional(
      t.Union([
        t.Union([t.String({ maxLength: 5000 }), ProductSchema, DeletedProductSchema], {
          description: 'The product whose pricing this plan determines.',
        }),
        t.Null(),
      ]),
    ),
    tiers: t.Optional(
      t.Array(PlanTierSchema, {
        description:
          'Each element represents a pricing tier. This parameter requires `billing_scheme` to be set to `tiered`. See also the documentation for `billing_scheme`.',
      }),
    ),
    tiers_mode: t.Optional(
      t.Union([
        t.UnionEnum(['graduated', 'volume'], {
          description:
            'Defines if the tiering price should be `graduated` or `volume` based. In `volume`-based tiering, the maximum quantity within a period determines the per unit price. In `graduated` tiering, pricing can change as the quantity grows.',
          default: undefined,
        }),
        t.Null(),
      ]),
    ),
    transform_usage: t.Optional(t.Union([TransformUsageSchema, t.Null()])),
    trial_period_days: t.Optional(
      t.Union([
        t.Integer({
          maximum: 9007199254740991,
          description:
            'Default number of trial days when subscribing a customer to this plan using [`trial_from_plan=true`](https://docs.stripe.com/api#create_subscription-trial_from_plan).',
        }),
        t.Null(),
      ]),
    ),
    usage_type: t.UnionEnum(['licensed', 'metered'], {
      description:
        'Configures how the quantity per period should be determined. Can be either `metered` or `licensed`. `licensed` automatically bills the `quantity` set when adding it to a subscription. `metered` aggregates the total usage based on usage records. Defaults to `licensed`.',
      default: undefined,
    }),
  },
  {
    title: 'Plan',
    description:
      'You can now model subscriptions more flexibly using the [Prices API](https://docs.stripe.com/api#prices). It replaces the Plans API and is backwards compatible to simplify your migration.\n\nPlans define the base price, currency, and billing cycle for recurring purchases of products.\n[Products](https://docs.stripe.com/api#products) help you track inventory or provisioning, and plans help you track pricing. Different physical goods or levels of service should be represented by products, and pricing options should be represented by plans. This approach lets you change prices without having to change your provisioning scheme.\n\nFor example, you might have a single "gold" product that has plans for $10/month, $100/year, €9/month, and €90/year.\n\nRelated guides: [Set up a subscription](https://docs.stripe.com/billing/subscriptions/set-up-subscription) and more about [products and prices](https://docs.stripe.com/products-prices/overview).',
  },
)

